def fact(n):   # Function for calculating Factorial of a number using Recursion   
     if n == 0 or n==1:     
          return 1      
     else:                  
           return (n * fact(n-1))        


def last_Digit_Factorial(num):   # Function to find the Last Digit in Factorial of a number   
